import 'dart:io'; import 'dart:convert'; void main() { for (var lang in ['en', 'hi', 'ta']) { var file = File('lib/localization/$lang.json'); if (file.existsSync()) { var map = json.decode(file.readAsStringSync()); var newMap = {}; map.forEach((k, v) { newMap[k] = v.toString().replaceAll(RegExp(r'^\[(EN|HI|TA)\]\s*'), ''); }); file.writeAsStringSync(json.encode(newMap)); print('Cleaned $lang.json'); } } }
